function tasteIntelligence(){
 const t=studio.taste,question=t.questions[0],confirmed=t.observations.filter(p=>p.stance!=='unknown'),reacted=t.observations.filter(p=>p.stance==='unknown'&&p.confirmed),tentative=t.observations.filter(p=>p.stance==='unknown'&&!p.confirmed).sort((a,b)=>b.receipts-a.receipts);
 const tile=p=>`<details class="palette-piece ${p.stance==='unknown'&&!p.confirmed?'unconfirmed':'confirmed'}" data-signal="${p.signal}"><summary><span class="sensory-mark" aria-hidden="true">${{smoky:'≋',spicy:'✦',tangy:'◒',crispy:'▥',soft:'◡',rich:'▰',lighter:'⌁',paneer:'▦',cheese:'◩',noodles:'≋',rice:'⠿',bread:'▱'}[p.signal]||'·'}</span><strong>${esc(p.signal)}</strong><small>${esc(p.basis)}</small><span class="palette-state">${p.stance==='like'?'Enjoy · Edit':p.stance==='avoid'?'Avoid · Edit':p.stance==='neutral'?'Open · Edit':'+ Set preference'}</span></summary><p>How does this fit your taste?</p><div class="stance-options">${[['like','Enjoy'],['neutral','Open'],['avoid','Avoid']].map(([v,label])=>`<button data-preference="${p.signal}" data-stance="${v}" class="${p.stance===v?'active':''}" aria-pressed="${p.stance===v}">${label}</button>`).join('')}</div></details>`;
 return `<section class="taste-intelligence"><div class="taste-proof"><strong>${t.evidence.length}</strong><div><h2>Confirmed dish ${t.evidence.length===1?'reaction':'reactions'}.</h2><p>${result.profile.orderCount} receipts are clues; your own reactions teach enjoyment.</p><p class="palette-instruction">Tap a flavour to set Enjoy / Open / Avoid.</p></div></div>${confirmed.length?`<div class="palette-group"><p class="eyebrow">PREFERENCES YOU STATED</p><div class="sensory-palette stated-palette">${confirmed.map(tile).join('')}</div></div>`:''}${reacted.length?`<div class="palette-group"><p class="eyebrow">NAME-BASED QUALITIES OF DISHES YOU REACTED TO · NOT STATED PREFERENCES</p><div class="sensory-palette reacted-palette">${reacted.map(tile).join('')}</div></div>`:''}<div class="palette-group tentative"><p class="eyebrow">POSSIBILITIES FROM DISH NAMES · ENJOYMENT UNCONFIRMED</p><div class="sensory-palette tentative-palette">${tentative.slice(0,6).map(tile).join('')}</div>${tentative.length>6?`<details class="more-flavours"><summary>${tentative.length-6} more flavours to give meaning</summary><div class="sensory-palette tentative-palette">${tentative.slice(6).map(tile).join('')}</div></details>`:''}<p class="hint">Texture and flavour names are interpretations. Open a tile to give it your meaning.</p></div>${question?`<div class="learning-question"><span class="question-mark">?</span><div><strong>${esc(question.text)}</strong><p>A lasting preference is yours to confirm.</p><button data-preference="${question.signal}" data-stance="like">Yes, I enjoy it</button><button data-preference="${question.signal}" data-stance="neutral">It depends</button></div></div>`:''}${state.preferences.some(p=>p.scope!=='always')?`<div class="context-preferences"><h3>For a particular food mood</h3>${state.preferences.filter(p=>p.scope!=='always').map(p=>`<div class="preference-row"><div><strong>${esc(p.signal)}</strong><small>For ${esc(p.scope)} · you confirmed this</small></div><div class="stance-options">${[['like','Enjoy'],['neutral','Open'],['avoid','Avoid']].map(([v,label])=>`<button data-preference="${p.signal}" data-scope="${p.scope}" data-stance="${v}" class="${p.stance===v?'active':''}">${label}</button>`).join('')}</div></div>`).join('')}</div>`:''}<div class="confirmed-evidence">${t.evidence.slice(0,4).map(e=>`<button data-order="${esc(e.orderId)}"><strong>${esc(e.name)}</strong><span>${esc(e.reaction)} · ${esc(e.mood)}${e.reason==='convenience'?' · convenience also mattered':''} ↗</span></button>`).join('')}</div></section><section class="food-memories"><p class="eyebrow">YOUR LITTLE RITUALS</p><h2>More than a receipt.</h2>${state.memories.length?state.memories.map(m=>`<article><button data-order="${esc(m.orderId)}"><strong>${esc(m.title)}</strong></button><span>${esc({any:'A meal to revisit',weekend:'Weekend ritual',outing:'An outing',celebration:'A celebration'}[m.occasion]||'A meal to revisit')}</span><p>${esc(m.note)}</p><button data-delete-memory="${esc(m.id)}">Remove memory</button></article>`).join(''):'<p>Save the meal, the company, something to recreate. Your journal has room for it.</p><button data-view="history" class="secondary">Find a meal to remember ↗</button>'}</section>`;
}
